const x=$input.first()?.json||{},e=x.execution||{},w=x.workflow||{};
const message=String(e.error?.message||'').slice(0,2000);
let reason='EXECUTION_FAILED';
if(/(?:\b401\b|unauthori[sz]ed|invalid token|authentication failed)/i.test(message))reason='AUTH_FAILED';
else if(/(?:\b403\b|\b1010\b|forbidden|access denied)/i.test(message))reason='ACCESS_DENIED';
else if(/(?:\b429\b|rate limit)/i.test(message))reason='RATE_LIMITED';
else if(/(?:\b50[234]\b|timeout|timed out|econnreset|network error)/i.test(message))reason='TRANSIENT_PROVIDER_FAILURE';
const workflow_id=/^[\w-]{1,100}$/.test(String(w.id||''))?String(w.id):'';
const execution_id=/^\d{1,18}$/.test(String(e.id||''))?String(e.id):'';
return [{json:{kind:'n8n_error',status:'FAILED',workflow_id,execution_id,reason_code:reason,
  retry_policy:['RATE_LIMITED','TRANSIENT_PROVIDER_FAILURE'].includes(reason)?'REVIEW_BOUNDED_RETRY':'MANUAL_REVIEW',
  evidence_level:'sanitized_error_trigger',outbound_send_enabled:false}}];
